
  .pageitem {
    // border: 1px solid #ffffff;
    position: absolute;
    top: 0;
    bottom: 0;
    left: 0;
    right: 0;
    overflow: auto;
    .topbar {
      position: sticky;
      z-index: 99;
      background: #212534;
      padding-bottom: 10px;
      top: 0;
      .bookmarks {
        cursor: pointer;
        display: flex;
        grid-gap: 20px;
        max-width: 1400px;
        width: 100%;
        margin: 10px auto 0;
        // overflow: auto;
        padding: 10px 20px 20px;
        justify-content: flex-start;
        // flex-wrap: wrap;
        .plat-item {
          display: flex;
          justify-content: center;
          align-items: center;
          background: #212534;
          img {
            max-height: 15px;
            filter: grayscale(1);
          }
          span {
            color: rgba(200, 200, 200, 0.5);
            font-size: 20px;
            font-weight: bold;
          }
          &.active {
            background: #2b2b4b;
            box-shadow: inset 0 0 5px #ffffff;
            img {
              filter: grayscale(0);
            }
            span {
              color: #ffffff;
            }
          }
        }
        div {
          padding: 10px;
          text-align: center;
          background: #2b2b4b;
          border-radius: 10px;
          box-shadow: rgb(0 0 0 / 24%) 0px 6px 12px 0px;
          &:hover {
            // transform: scale(1.01274) translate(0px, -4px);
          }
        }
      }
    }
    .grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 10px;
      width: 90%;
      margin: 0 auto;
      :deep(.zoomin) {
        transform: scale(1.3);
      }
      .inner-img {
        border-radius: 20px;
        overflow: hidden;
        position: relative;
      }
      .slot-name {
        background: linear-gradient(0deg, #1f2035cf 20%, transparent);
        position: absolute;
        bottom: 0;
        left: 0;
        right: 0;
        padding: 10px;
        text-align: center;
      }
    }

  }
  .loading-div{
    z-index: 99;
    position:absolute;
    top: 0;
    background: rgba(35,38,60,0.6);
    text-align:center;
    width: 100%;
    height: 100%;
    display:flex;
    align-items: center;
    justify-content: center;
    svg{
      color: #db7e42;
      width:48px;
    }
  }
